arguments.file_text:
@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Models

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" @bind="Model.FullName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control @(emailError != null ? "is-invalid" : "")"
               @bind="Model.Email" @bind:event="oninput" />
        @if (emailError != null)
        {
            <div class="validation-error">@emailError</div>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" @bind="Model.Phone" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <input type="text" class="form-control" @bind="Model.Address" @bind:event="oninput" />
    </div>

    @if (validationMessage != null)
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @(isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? validationMessage;
    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        validationMessage = null;
        emailError = null;

        if (!Model.IsValid())
        {
            validationMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ValidateEmail(Model.Email);
            if (!emailValid)
            {
                emailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}

@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Models

<div class="step-content">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (validationMessage != null)
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (!Entries.All(e => e.IsValid()))
        {
            validationMessage = "Please fill in company name and job title for all entries.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Models

<div class="step-content">
    <h3>References</h3>
    <p class="text-muted">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="index"
                       ShowRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (validationMessage != null)
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (References.Count < 2)
        {
            validationMessage = "Please provide at least 2 references.";
            return;
        }

        if (!References.All(r => r.IsValid()))
        {
            validationMessage = "Please fill in all fields for each reference.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Models

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="form-control cover-letter-textarea"
                  rows="12"
                  maxlength="@MaxLength"
                  @bind="CoverLetter"
                  @bind:event="oninput"
                  @bind:after="NotifyChanged"></textarea>
        <div class="character-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task NotifyChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }
}

.cover-letter-textarea {
    font-family: inherit;
    resize: vertical;
    min-height: 200px;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.character-count.over-limit {
    color: #dc3545;
    font-weight: bold;
}

@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Models

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We'll be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="work-review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") &mdash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>References</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="reference-review-entry">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    <span class="text-muted">@reference.Email &bull; @reference.Phone</span>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (errorMessage != null)
        {
            <div class="validation-error">@errorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @(isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public Func<Task<int>> OnSubmit { get; set; } = default!;
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }

    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;

        try
        {
            await OnSubmit();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

