arguments.file_text:
@page "/apply"
@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Components.Apply
@using sv_0fe489e059134a959f4ddb33ffdd3f9a.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo"
                              ValidateEmail="ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="val => coverLetter = val"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        OnBack="PreviousStep"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitAsync"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep;
    private bool isSubmitted;
    private int? applicationId;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;

    private Task<bool> ValidateEmailAsync(string email) =>
        ApplicationService.ValidateEmailAsync(email);

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            personalInfo.ToRecord(),
            new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
            references.Select(r => r.ToRecord()).ToList(),
            coverLetter
        );

        var id = await ApplicationService.SubmitApplicationAsync(application);
        applicationId = id;
        isSubmitted = true;
        return id;
    }
}

.apply-container {
    max-width: 720px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-container h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

/* Shared form styles */
:deep(.form-group) {
    margin-bottom: 1rem;
}

:deep(.form-group label) {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

:deep(.form-control) {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

:deep(.form-control:focus) {
    outline: none;
    border-color: #1a73e8;
    box-shadow: 0 0 0 2px rgba(26, 115, 232, 0.2);
}

:deep(.form-control.is-invalid) {
    border-color: #dc3545;
}

:deep(.form-row) {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

:deep(.checkbox-label) {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
    font-size: 0.85rem;
}

:deep(.step-buttons) {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

:deep(.btn) {
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    border: 1px solid transparent;
}

:deep(.btn-primary) {
    background: #1a73e8;
    color: white;
}

:deep(.btn-primary:hover) {
    background: #1557b0;
}

:deep(.btn-secondary) {
    background: #f1f3f4;
    color: #333;
    border-color: #ccc;
}

:deep(.btn-success) {
    background: #34a853;
    color: white;
}

:deep(.btn-success:hover) {
    background: #2d8f47;
}

:deep(.btn-outline-secondary) {
    background: transparent;
    border-color: #ccc;
    color: #555;
}

:deep(.btn-outline-danger) {
    background: transparent;
    border-color: #dc3545;
    color: #dc3545;
}

:deep(.btn-link) {
    background: none;
    border: none;
    color: #1a73e8;
    padding: 0;
    text-decoration: underline;
    cursor: pointer;
}

:deep(.btn:disabled) {
    opacity: 0.6;
    cursor: not-allowed;
}

:deep(.btn-lg) {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

:deep(.validation-error) {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.5rem;
}

:deep(.text-muted) {
    color: #666;
    font-size: 0.85rem;
}

:deep(.mt-1) {
    margin-top: 0.25rem;
}

